/// <summary>
/// Handles the extendes logic behind the login process.
/// </summary>
[
    WHSWorkExecuteMode(WHSWorkExecuteMode::AVALoginPrinter)
]
class AVAWhsWorkExecuteDisplayLoginPrinter extends WhsWorkExecuteDisplayLogin
{
}

Method.Source:
/// <summary>
/// Create work user session and add to container containing the form state.
/// </summary>
/// <param name="_con">
/// Container containing the form state before the controls are added.
/// </param>
/// <param name="_inventLocationId">
/// Inventory location value to be set on the session.
/// </param>
/// <returns>
/// Container containing the form state after user session control is added.
/// </returns>
protected container createWorkUserSession(
    container           _con,
    InventLocationId    _inventLocationId)
{
    container               avaRet;
    WHSMenuItemName         avaWHSPrinterMenuItemName;
    WHSWorkUser             avaWHSworkUser;
    WHSWorkExecuteDisplay   avaWorkExecuteDisplay;

    avaRet = super(_con, _inventLocationId);

    avaWHSworkUser = WHSWorkUser::find(userId);

    if (avaWHSworkUser)
    {
        if (avaWHSworkUser.AVAUserDefaultPrinterCode)
        {
            this.avaUpdatePrinter(avaWHSworkUser.UserId, avaWHSworkUser.AVAUserDefaultPrinterCode);
        }

        avaWHSPrinterMenuItemName = this.avaSearchPrinterMenu();

        if (avaWHSworkUser.AVALoginAndChangePrinter == NoYes::Yes
         && avaWHSPrinterMenuItemName)
        {
            avaRet = this.updateModeStepPass(avaRet, mode, step, pass);

            avaWorkExecuteDisplay = WHSWorkExecuteDisplay::construct(WHSWorkExecuteMode::Menu);

            avaRet = avaWorkExecuteDisplay.displayForm(avaRet, avaWHSPrinterMenuItemName);
        }
    }

    return avaRet;
}

private WHSMenuItemName avaSearchPrinterMenu()
{
    WHSMenuItemName     avaWHSMenuItemName;
    WHSRFMenuItemTable  avaWHSRFMenuItemTable;

    select firstonly RecId, MenuItemName from avaWHSRFMenuItemTable
        where avaWHSRFMenuItemTable.WorkActivity == WHSWorkActivity::AVAChangePrinter;

    if (avaWHSRFMenuItemTable)
    {
        avaWHSMenuItemName = avaWHSRFMenuItemTable.MenuItemName;
    }

    return avaWHSMenuItemName;
}

/// <summary>
/// Update Printer in the session.
/// </summary>
/// <param name="_userId">
/// User id of the session.
/// </param>
/// <param name="_printerCode">
/// Printer code to be set into session.
/// </param>
protected void avaUpdatePrinter(WHSUserId _userId, AVAPrinterCode _printerCode)
{
    WHSWorkUserSession::avaUpdatePrinter(_userId, _printerCode);
}
